Tool error (bash): /// `dmtools upgrade [version]` (alias `update`).
///
/// The Dart distribution ships as an AOT binary plus a QuickJS library, both
/// installed by `install.sh` under `~/.dmtools/bin`. Upgrading therefore reuses
/// that installer (the same mechanism as first install) instead of replacing
/// the running executable in place.
///
/// Flow: resolve the install script URL, download it to a temp file (failure
/// exits non-zero before anything is touched), then run it with `sh`.
library;

import 'dart:io';

import '../version.dart';

/// Default installer location for the latest release.
const String _latestInstallUrl =
    'https://github.com/epam/dmtools-dart/releases/latest/download/install.sh';

/// Upgrade runner. All side effects are injectable for tests.
class UpgradeCommand {
  /// Creates an upgrade runner.
  UpgradeCommand({
    void Function(String line)? writer,
    Map<String, String>? environment,
    Future<String?> Function(String url)? fetchScript,
    Future<int> Function(String scriptPath, Map<String, String> env)? runScript,
  })  : _writer = writer ?? print,
        _env = environment ?? Platform.environment,
        _fetch = fetchScript ?? _defaultFetch,
        _run = runScript ?? _defaultRun;

  final void Function(String line) _writer;
  final Map<String, String> _env;
  final Future<String?> Function(String url) _fetch;
  final Future<int> Function(String scriptPath, Map<String, String> env) _run;

  /// Runs the upgrade. [args] holds the optional version (`upgrade 0.1.60`
  /// or `upgrade v0.1.60`). Returns the process exit code.
  Future<int> run(List<String> args) async {
    final help = _helpExit(args);
    if (help != null) return help;
    final version = _resolveRequestedVersion(args);
    final url = _resolveUrl(version);
    final before = dmtoolsVersion;

    _writer('Installed version: $before');
    _writer('Installer: $url');

    if (_env['DMTOOLS_UPGRADE_DRY_RUN'] == 'true') {
      _writer(
        'Dry run: would run the installer above'
        '${version.isEmpty ? '' : ' for $version'}. No changes made.',
      );
      return 0;
    }

    final script = await _fetch(url);
    if (script == null) {
      _downloadFailed(url);
      return 1;
    }
    final env = Map<String, String>.from(_env);
    if (version.isNotEmpty) env['DMTOOLS_VERSION'] = version;
    final code = await _run(script, env);
    if (code != 0) return _installFailed(code);
    _writer(
      'Upgraded: $before -> ${_displayVersion(version)}'
      '. Run `dmtools --version` to confirm.',
    );
    return 0;
  }

  /// The version to upgrade to: the positional arg wins, else
  /// `DMTOOLS_VERSION`, else latest (empty string).
  String _resolveRequestedVersion(List<String> args) {
    final positional = args.where((a) => !a.startsWith('-')).toList();
    final requested = positional.isEmpty ? null : positional.first.trim();
    if (requested == null || requested.isEmpty) {
      return _env['DMTOOLS_VERSION'] ?? '';
    }
    return requested;
  }

  /// Prints the usage line for `--help`/`-h`; null when args are real work.
  int? _helpExit(List<String> args) {
    if (args.any((a) => a == '--help' || a == '-h')) {
      _writer('Usage: dmtools upgrade [version]   (alias: update)');
      return 0;
    }
    return null;
  }

  /// Reports a failed download; the installation is left untouched.
  int _downloadFailed(String url) {
    _writer(
      'Upgrade failed: could not download $url. '
      'The existing installation was left untouched.',
    );
    return 1;
  }

  /// Reports a failed installer run; the installation is left untouched.
  int _installFailed(int code) {
    _writer(
      'Upgrade failed: installer exited with code $code. '
      'The existing installation was left untouched.',
    );
    return code;
  }

  /// The human-facing version label: `latest` or the requested one, `v`-less.
  String _displayVersion(String version) =>
      version.isEmpty ? 'latest' : version.replaceFirst(RegExp(r'^v'), '');

  /// Resolves the installer URL. `DMTOOLS_INSTALL_SCRIPT_URL` wins; a
  /// version selects the tagged release asset, otherwise the latest one.
  String _resolveUrl(String version) {
    final override = _env['DMTOOLS_INSTALL_SCRIPT_URL'];
    if (override != null && override.isNotEmpty) return override;
    if (version.isEmpty) return _latestInstallUrl;
    final tag = version.startsWith('v') ? version : 'v$version';
    return 'https://github.com/epam/dmtools-dart/releases/download/$tag/install.sh';
  }

  static Future<String?> _defaultFetch(String url) async {
    final client = HttpClient();
    try {
      final req = await client.getUrl(Uri.parse(url));
      final res = await req.close();
      if (res.statusCode != 200) {
        await res.drain<void>();
        return null;
      }
      final body = await res.transform(const SystemEncoding().decoder).join();
      final file = await File(
        '${Directory.systemTemp.path}/dmtools-install-${DateTime.now().microsecondsSinceEpoch}.sh',
      ).create();
      await file.writeAsString(body);
      return file.path;
    } catch (_) {
      return null;
    } finally {
      client.close(force: true);
    }
  }

  static Future<int> _defaultRun(
    String scriptPath,
    Map<String, String> env,
  ) async {
    final result = await Process.run('sh', [scriptPath], environment: env);
    stdout.write(result.stdout);
    stderr.write(result.stderr);
    return result.exitCode;
  }
}
import 'dart:io';

import 'package:dmtools/src/cli/help_text.dart';
import 'package:dmtools/src/cli/upgrade_command.dart';
import 'package:test/test.dart';

void main() {
  _helpTextTests();
  _upgradeDryRunTests();
  _upgradeInstallerTests();
  _upgradeDownloadTests();
}

void _helpTextTests() {
  group('help output formats', () {
    test('every supported output format is documented', () {
      for (final f in ['json', 'toon', 'mini', 'short', 'table', 'mermaid']) {
        expect(cliHelpText, contains(f));
      }
      expect(
        cliHelpText,
        contains('--output <json|toon|mini|short|table|mermaid>'),
      );
      expect(cliHelpText, contains('--toon'));
      expect(cliHelpText, contains('--mini'));
      expect(cliHelpText, contains('CLI_OUTPUT'));
    });

    test('documents upgrade command', () {
      expect(cliHelpText, contains('dmtools upgrade [version]'));
    });

    test('upgrade --help prints usage and exits 0 without downloading',
        () async {
      final lines = <String>[];
      var fetched = false;
      final code = await UpgradeCommand(
        writer: lines.add,
        environment: {},
        fetchScript: (_) async {
          fetched = true;
          return null;
        },
      ).run(['--help']);
      expect(code, 0);
      expect(fetched, isFalse);
      expect(lines.join('\n'), contains('Usage: dmtools upgrade [version]'));
    });
  });
}

void _upgradeDryRunTests() {
  group('UpgradeCommand dry-run and download failures', () {
    test('dry run makes no download or install', () async {
      final lines = <String>[];
      var fetched = false;
      final code = await UpgradeCommand(
        writer: lines.add,
        environment: {'DMTOOLS_UPGRADE_DRY_RUN': 'true'},
        fetchScript: (_) async {
          fetched = true;
          return null;
        },
      ).run([]);
      expect(code, 0);
      expect(fetched, isFalse);
      expect(lines.join('\n'), contains('Dry run'));
    });

    test('failed download exits non-zero and does not run installer', () async {
      final lines = <String>[];
      var ran = false;
      final code = await UpgradeCommand(
        writer: lines.add,
        environment: {},
        fetchScript: (_) async => null,
        runScript: (_, __) async {
          ran = true;
          return 0;
        },
      ).run(['0.1.60']);
      expect(code, 1);
      expect(ran, isFalse);
      expect(lines.join('\n'), contains('left untouched'));
    });
  });
}

void _upgradeInstallerTests() {
  group('UpgradeCommand installer selection', () {
    test('version selects tagged installer and passes DMTOOLS_VERSION',
        () async {
      String? url;
      Map<String, String>? seenEnv;
      final code = await UpgradeCommand(
        writer: (_) {},
        environment: {},
        fetchScript: (u) async {
          url = u;
          return '/tmp/x.sh';
        },
        runScript: (_, env) async {
          seenEnv = env;
          return 0;
        },
      ).run(['0.1.60']);
      expect(code, 0);
      expect(
        url,
        'https://github.com/epam/dmtools-dart/releases/download/v0.1.60/install.sh',
      );
      expect(seenEnv?['DMTOOLS_VERSION'], '0.1.60');
    });
  });
}

Future<HttpServer> _spawnUpgradeStub() async {
  final server = await HttpServer.bind('127.0.0.1', 0);
  server.listen((req) async {
    if (req.uri.path == '/ok') {
      req.response.write('#!/bin/sh\necho ok\n');
      await req.response.close();
    } else {
      req.response.statusCode = 404;
      await req.response.close();
    }
  });
  return server;
}

void _upgradeDownloadTests() {
  group('UpgradeCommand download path', () {
    Future<int> runWith(String path, void Function(String) onScript) async {
      final server = await _spawnUpgradeStub();
      addTearDown(server.close);
      final ran = <String>[];
      final code = await UpgradeCommand(
        writer: (_) {},
        environment: {
          'DMTOOLS_INSTALL_SCRIPT_URL': 'http://127.0.0.1:${server.port}$path',
        },
        runScript: (script, _) async {
          onScript(script);
          ran.add(script);
          return 0;
        },
      ).run(['0.1.60']);
      expect(ran.length, ran.isNotEmpty ? 1 : 0);
      return code;
    }

    test('200: the fetched script is staged and executed', () async {
      final ran = <String>[];
      expect(await runWith('/ok', ran.add), 0);
      expect(File(ran.single).readAsStringSync(), contains('echo ok'));
    });

    test('404: download failure, installer never runs', () async {
      expect(await runWith('/nope', (_) {}), 1);
    });

    test('connection refused: catch branch, clean exit 1', () async {
      final server = await _spawnUpgradeStub();
      addTearDown(server.close);
      final dead = await UpgradeCommand(
        writer: (_) {},
        environment: {
          'DMTOOLS_INSTALL_SCRIPT_URL': 'http://127.0.0.1:1/x.sh',
        },
        runScript: (_, __) async => 0,
      ).run(['0.1.60']);
      expect(dead, 1);
    });
  });
}

